// RegisterCodeOrchestrationTools registers the two agent-facing tools that
// cover the whole API surface. Called from RegisterTools in place of the
// per-endpoint registrations when MCP.Orchestration is "code".
func RegisterCodeOrchestrationTools(s *server.MCPServer) {
	s.AddTool(
		mcplib.NewTool("scalify_search",
			mcplib.WithDescription("Search the scalify API for endpoints matching a natural-language query. Returns a ranked list of {endpoint_id, method, path, summary, params} entries; params lists the path, query and body fields (* = required, then :type). Call this first to find the endpoint to execute."),
			mcplib.WithString("query", mcplib.Required(), mcplib.Description("Natural-language description of what you want to do.")),
			mcplib.WithNumber("limit", mcplib.Description("Max endpoints to return (default 10).")),
		),
		scalifySearch,
	)

	s.AddTool(
		mcplib.NewTool("scalify_execute",
			mcplib.WithDescription("Execute one scalify API endpoint by its endpoint_id (from scalify_search). Params are one flat JSON object: path and query fields are taken out by name, the rest is the JSON body (POST/PUT/PATCH) or query string (GET/DELETE). locationId defaults to the active location."),
			mcplib.WithString("endpoint_id", mcplib.Required(), mcplib.Description("Endpoint identifier returned by scalify_search (e.g., \"users.list\").")),
			mcplib.WithObject("params", mcplib.Description("Parameters for the endpoint. Flat object of the endpoint's params, by name (see params in scalify_search results).")),
		),
		scalifyExecute,
	)
}

